1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.MembershipLevel;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class, imports = {MembershipLevel.class})
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "selfLink",
23	            expression = "java(\"/api/owners/\" + owner.getId())")
24	    @Mapping(target = "displayName",
25	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
26	    @Mapping(target = "salutation",
27	            expression = "java(owner.getTitle() == null || owner.getTitle().isBlank() ? owner.getLastName() : owner.getTitle() + \" \" + owner.getLastName())")
28	    @Mapping(target = "initials",
29	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
30	    @Mapping(target = "telephoneDisplay",
31	            expression = "java(TelephoneDisplay.of(owner.getTelephone()))")
32	    @Mapping(target = "fiscalYear",
33	            expression = "java(MemberId.fiscalYear(owner.getMemberId()))")
34	    @Mapping(target = "membershipPoints",
35	            expression = "java(MembershipLevel.points(owner))")
36	    @Mapping(target = "membershipLevel",
37	            expression = "java(MembershipLevel.of(owner))")
38	    @Mapping(target = "locality",
39	            expression = "java(Locality.of(owner.getMemberId()))")
40	    @Mapping(target = "timezone",
41	            expression = "java(Timezone.of(Locality.of(owner.getMemberId())))")
42	    @Mapping(target = "contactPreference",
43	            expression = "java(ContactPreference.of(owner.getEmail()))")
44	    @Mapping(target = "ageBand",
45	            expression = "java(AgeBand.of(owner))")
46	    @Mapping(target = "ownerSegment",
47	            expression = "java(OwnerSegment.of(owner))")
48	    @Mapping(target = "riskFlag",
49	            expression = "java(RiskFlag.of(owner))")
50	    OwnerDto toOwnerDto(Owner owner);
51	
52	    Owner toOwner(OwnerDto ownerDto);
53	
54	    @Mapping(target = "id", ignore = true)
55	    @Mapping(target = "pets", ignore = true)
56	    Owner toOwner(OwnerFieldsDto ownerDto);
57	
58	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
59	
60	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
61	
62	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
63	        OwnerPageDto ownerPageDto = new OwnerPageDto();
64	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
65	        ownerPageDto.setPage(ownerPage.getNumber());
66	        ownerPageDto.setSize(ownerPage.getSize());
67	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
68	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
69	        return ownerPageDto;
70	    }
71	}
