1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Reads sub-values back out of an owner's unified {@code memberId}
5	 * ({@code <REGION><FY><HASH8><CHK>}), so the DTO fields derived from the identity stay consistent
6	 * with the id itself rather than being recomputed from other owner fields.
7	 *
8	 * <p>Kept as a standalone helper (referenced from {@link OwnerMapper}'s {@code fiscalYear}
9	 * expression) rather than a mapper {@code default} method to avoid MapStruct picking it up as an
10	 * automatic conversion.
11	 */
12	final class MemberId {
13	
14	    private MemberId() {
15	    }
16	
17	    /**
18	     * The fiscal-year label {@code FY<YY>} taken from the two FY digits that follow the region
19	     * prefix of {@code memberId}, or {@code null} when the id is absent or too short to carry them.
20	     */
21	    static String fiscalYear(String memberId) {
22	        String region = Locality.of(memberId);
23	        if (memberId == null || memberId.length() < region.length() + 2) {
24	            return null;
25	        }
26	        return "FY" + memberId.substring(region.length(), region.length() + 2);
27	    }
28	}
