1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.List;
4	
5	/**
6	 * Derives an owner's canonical region ('locality') from its {@code memberId}. Owner identity is
7	 * {@code <REGION><FY><HASH8><CHK>} (assigned at registration from the owner's postcode, registration
8	 * date and a hash of its telephone and last name), so the locality is the leading REGION component.
9	 * It is {@code "UNKNOWN"} when no id has been assigned or the id carries no known region prefix.
10	 *
11	 * <p>Kept as a standalone helper (referenced from {@link OwnerMapper}'s
12	 * {@code locality} expression) rather than a mapper {@code default} method: a
13	 * {@code String}-to-{@code String} method on the mapper interface would be
14	 * picked up by MapStruct as an automatic conversion for every String property.
15	 */
16	final class Locality {
17	
18	    static final String UNKNOWN = "UNKNOWN";
19	
20	    /** The known region prefixes a memberId can start with (everything else is {@code UNKNOWN}). */
21	    private static final List<String> REGIONS = List.of("NSW", "VIC", "QLD");
22	
23	    private Locality() {
24	    }
25	
26	    /**
27	     * The REGION component of the owner's {@code memberId} — its leading region prefix — or
28	     * {@code "UNKNOWN"} when the id is absent or begins with no known region.
29	     */
30	    static String of(String memberId) {
31	        if (memberId == null) {
32	            return UNKNOWN;
33	        }
34	        for (String region : REGIONS) {
35	            if (memberId.startsWith(region)) {
36	                return region;
37	            }
38	        }
39	        return UNKNOWN;
40	    }
41	}
