1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's IANA timezone ('timezone') from its canonical region
7	 * ('locality') via the fixed region-to-timezone table
8	 * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
9	 * {@code QLD -> Australia/Brisbane}). Regions outside the table (including
10	 * {@link Locality#UNKNOWN}) have no known timezone and yield {@code null}.
11	 *
12	 * <p>Kept as a standalone helper (referenced from {@link OwnerMapper}'s
13	 * {@code timezone} expression) rather than a mapper {@code default} method to
14	 * avoid MapStruct picking it up as an automatic conversion.
15	 */
16	final class Timezone {
17	
18	    /** Region -&gt; IANA timezone. Anything not listed has no known timezone. */
19	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
20	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
21	
22	    private Timezone() {
23	    }
24	
25	    /**
26	     * The IANA timezone name for the given region, or {@code null} when the region
27	     * is absent or has no entry in the fixed table.
28	     */
29	    static String of(String region) {
30	        return region == null ? null : REGION_TIMEZONE.get(region);
31	    }
32	}
