1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.HashSet;
6	import java.util.Map;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.FiscalYear;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's unified {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>}:
16	 * <ul>
17	 *   <li>REGION — the region code derived from the owner's postcode (its inclusive range:
18	 *   {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}, else {@code UNKNOWN});</li>
19	 *   <li>FY — the two-digit fiscal year (starting 1 July) of the owner's registrationDate;</li>
20	 *   <li>HASH8 — the first 8 upper-case hex characters of {@code SHA-256} over the owner's normalized
21	 *   telephone concatenated with its last name;</li>
22	 *   <li>CHK — a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}.</li>
23	 * </ul>
24	 * (e.g. {@code NSW261A2B3C4D5}.)
25	 *
26	 * <p>The identity is derived deterministically from the owner's own fields — no sequence numbers —
27	 * so it does not depend on other owners or on creation order. The telephone has already been
28	 * normalized to E.164 form by {@link ValidateOwnerFields}, and the registrationDate rolled to a
29	 * business day by {@link BuildOwner}, before this step runs.
30	 *
31	 * <p>Should the deterministic id collide with an existing owner's {@code memberId}, it is
32	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
33	 * unique (e.g. {@code NSW261A2B3C4D5}, then {@code NSW261A2B3C4D5-2}, {@code NSW261A2B3C4D5-3}, …).
34	 */
35	public class AssignMemberId {
36	
37	    /** Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. */
38	    private static final Map<String, int[]> REGION_RANGE = Map.of(
39	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
40	
41	    private static final String UNKNOWN = "UNKNOWN";
42	
43	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
44	        String region = regionOf(owner.getPostcode());
45	        String fy = String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100);
46	        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
47	        String withoutCheck = region + fy + hash8;
48	        String base = withoutCheck + luhn(withoutCheck);
49	
50	        Set<String> taken = new HashSet<>();
51	        for (Owner existing : ownerRepository.findAll()) {
52	            if (existing.getMemberId() != null) {
53	                taken.add(existing.getMemberId());
54	            }
55	        }
56	
57	        String memberId = base;
58	        for (int n = 2; taken.contains(memberId); n++) {
59	            memberId = base + "-" + n;
60	        }
61	        owner.setMemberId(memberId);
62	    }
63	
64	    /** The region whose inclusive range contains {@code postcode}, or {@code UNKNOWN} when the
65	     *  postcode is absent, not four digits, or in no known range. */
66	    private static String regionOf(String postcode) {
67	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
68	            return UNKNOWN;
69	        }
70	        int value = Integer.parseInt(postcode);
71	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
72	            int[] range = entry.getValue();
73	            if (value >= range[0] && value <= range[1]) {
74	                return entry.getKey();
75	            }
76	        }
77	        return UNKNOWN;
78	    }
79	
80	    /** The first 8 upper-case hex characters (4 bytes) of {@code SHA-256(value)}. */
81	    private static String hash8(String value) {
82	        try {
83	            byte[] digest = MessageDigest.getInstance("SHA-256")
84	                    .digest(value.getBytes(StandardCharsets.UTF_8));
85	            StringBuilder sb = new StringBuilder(8);
86	            for (int i = 0; i < 4; i++) {
87	                sb.append(String.format("%02X", digest[i]));
88	            }
89	            return sb.toString();
90	        }
91	        catch (Exception ex) {
92	            throw new IllegalStateException("SHA-256 unavailable", ex);
93	        }
94	    }
95	
96	    /** The single Luhn check digit (0-9) over the digits in {@code value}, ignoring non-digits.
97	     *  Alternate digits are doubled from the right, subtracting 9 from any doubled value over 9. */
98	    private static int luhn(String value) {
99	        int sum = 0;
100	        boolean dbl = true;
101	        for (int i = value.length() - 1; i >= 0; i--) {
102	            char c = value.charAt(i);
103	            if (c < '0' || c > '9') {
104	                continue;
105	            }
106	            int d = c - '0';
107	            if (dbl) {
108	                d *= 2;
109	                if (d > 9) {
110	                    d -= 9;
111	                }
112	            }
113	            sum += d;
114	            dbl = !dbl;
115	        }
116	        return (10 - (sum % 10)) % 10;
117	    }
118	}
