1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityConflictException;
8	
9	/**
10	 * Consolidated duplicate check for {@code POST /api/owners}. Rejects with 409
11	 * ({@link OwnerIdentityConflictException}) only when the new owner's whole {@code identityKey} — the
12	 * SHA-256 over normalized telephone {@code '|'} email {@code '|'} soundex(lastName), see
13	 * {@link Owner#getIdentityKey()} — exactly matches an existing owner's. Because the telephone is part
14	 * of the key, two members of the same household (same lastName and postcode) with different
15	 * telephones have different keys and are both allowed — the later one is instead flagged a soft match
16	 * by {@link AssignPossibleDuplicate}. The email-domain blocklist is applied earlier during field
17	 * validation, so a disposable-domain email is rejected before this check runs.
18	 *
19	 * <p>The {@code sharesHousehold} request flag bypasses this block: when set, the new owner is
20	 * created as a <em>declared</em> household member rather than rejected (and is not flagged a possible
21	 * duplicate — see {@link AssignPossibleDuplicate}). Runs before {@link SaveOwner} (so the new owner
22	 * is not yet in the repository scan).
23	 */
24	public class CheckOwnerIdentityUnique {
25	
26	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws OwnerIdentityConflictException {
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return; // declared household member: bypass the duplicate block
30	        }
31	        String identityKey = owner.getIdentityKey();
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (Boolean.TRUE.equals(existing.getDeleted())) {
34	                continue; // a soft-deleted owner never blocks a create
35	            }
36	            if (identityKey.equals(existing.getIdentityKey())) {
37	                throw new OwnerIdentityConflictException(identityKey);
38	            }
39	        }
40	    }
41	}
