3	import java.util.Locale;
4	
5	/**
6	 * Standard American Soundex encoding of a name: the first letter (upper-cased) followed by three
7	 * consonant-group digits (padded with zeros), so names that sound alike share a code. Used by the
8	 * owner {@link Owner#getIdentityKey() identity key} and the soft-match rule.
9	 *
10	 * <ul>
11	 *   <li>b, f, p, v &rarr; 1; c, g, j, k, q, s, x, z &rarr; 2; d, t &rarr; 3; l &rarr; 4;
12	 *       m, n &rarr; 5; r &rarr; 6.</li>
13	 *   <li>a, e, i, o, u, y, h, w are not coded. Adjacent letters with the same code (and letters with
14	 *       the same code separated only by h or w) collapse to a single digit; a vowel between them
15	 *       keeps both.</li>
16	 * </ul>
17	 */
18	public final class Soundex {
19	
20	    private Soundex() {
21	    }
22	
23	    /** The Soundex code of {@code value} (e.g. "Robert" &rarr; "R163"), or "" when it has no letters. */
24	    public static String encode(String value) {
25	        if (value == null) {
26	            return "";
27	        }
28	        StringBuilder letters = new StringBuilder();
29	        for (char c : value.toUpperCase(Locale.ROOT).toCharArray()) {
30	            if (c >= 'A' && c <= 'Z') {
31	                letters.append(c);
32	            }
33	        }
34	        if (letters.length() == 0) {
35	            return "";
36	        }
37	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
38	        char prevCode = codeOf(letters.charAt(0));
39	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
40	            char c = letters.charAt(i);
41	            char cc = codeOf(c);
42	            if (cc != '0' && cc != prevCode) {
43	                code.append(cc);
44	            }
45	            // h and w are transparent: they do not reset the previous code, so same-coded letters
46	            // on either side still collapse. Every other letter (including vowels) resets it.
47	            if (c != 'H' && c != 'W') {
48	                prevCode = cc;
49	            }
50	        }
51	        while (code.length() < 4) {
52	            code.append('0');
53	        }
54	        return code.toString();
55	    }
56	
57	    private static char codeOf(char c) {
58	        switch (c) {
59	            case 'B': case 'F': case 'P': case 'V':
60	                return '1';
61	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
62	                return '2';
63	            case 'D': case 'T':
64	                return '3';
65	            case 'L':
66	                return '4';
67	            case 'M': case 'N':
68	                return '5';
69	            case 'R':
70	                return '6';
71	            default: // A, E, I, O, U, Y, H, W
72	                return '0';
73	        }
74	    }
75	}
