3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.samples.petclinic.model.MembershipLevel;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Emits, on successful create via the dedicated {@code AUDIT} logger, both an audit line — carrying
13	 * the new owner's id, its {@code memberId}, its {@code registrationDate} and its
14	 * {@code membershipLevel} — and an immutable structured {@link OwnerCreatedEvent} rendered as JSON.
15	 *
16	 * <p>The event's {@code seq} is a process-wide monotonically increasing integer across creates, and
17	 * its identifier is the owner's {@link Owner#getPrimaryIdentifier() primary identifier} (the
18	 * unified {@code memberId}), so the event follows that identifier as it evolves.
19	 *
20	 * <p>Runs after {@link SaveOwner}, so the owner has been assigned its generated id, and before
21	 * {@link RespondWithOwnerCreated}, so both are written only once the create has succeeded.
22	 */
23	public class AuditOwnerCreated {
24	
25	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
26	
27	    /** Monotonically increasing event sequence, shared across all creates in this process. */
28	    private static final AtomicLong SEQUENCE = new AtomicLong();
29	
30	    public void service(@Val Owner owner) {
31	        AUDIT.info(
32	                "owner created id={} memberId={} registrationDate={} membershipLevel={}",
